solution:
enum State {
    case running(speed: Double)
    case finished
}

func describe(_ state: State) -> String {
    switch state {
    case .running(let speed): return "Running at \(speed)"
    case .finished: return "Done"
    }
}

print(describe(.running(speed: 2.5)))
print(describe(.finished))

