enum MathError: Error { case divisionByZero }

func divide(_ a: Int, _ b: Int) throws -> Int {
    guard b != 0 else { throw MathError.divisionByZero }
    return a / b
}

for b in [2, 0] {
    do {
        print("Result: \(try divide(10, b))")
    } catch {
        print("Error: \(error)")
    }
}

